def page(kicker,title,lead):
 if story:story.append(PageBreak())
 story.extend([p(kicker,'eyebrow'),p(title,'title'),p(lead,'lead')])
def card(title,what,why,how,color='#FFFFFF'):
 content=[p(title,'heading'),p(what),p('<b>Для чего:</b> '+why),p('<b>Как пользоваться:</b> '+how)]
 t=Table([[content]],colWidths=[499]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),HexColor(color)),('BOX',(0,0),(-1,-1),.5,HexColor('#E6DFF2')),('LEFTPADDING',(0,0),(-1,-1),16),('RIGHTPADDING',(0,0),(-1,-1),16),('TOPPADDING',(0,0),(-1,-1),14),('BOTTOMPADDING',(0,0),(-1,-1),10)]))
 story.extend([KeepTogether(t),Spacer(1,14)])
def note(text):story.append(p(text,'small'))

page('МАМИН ПОМОЩНИК / ОБНОВЛЕНИЕ СЕНТЯБРЬ 2026','Больше, чем разговор','Памятка для мам и пап: что нового добавили, зачем это нужно и как начать пользоваться.')
story.append(Image(str(ROOT/'public/logo-mark.png'),width=90,height=90,kind='proportional'))
story.append(Spacer(1,18))
card('От беременности до школы','Личный помощник для родителя и одного ребёнка до 6 лет включительно. Сохранили привычную палитру и добавили раздел «Мой день».','Чтобы не держать все вопросы и планы в голове.','Откройте сайт, войдите в личный аккаунт и проверьте профиль.','#EDE4FF')
story.append(p(f'<link href="{URL}" color="#6338C7"><b>Открыть «Мамин помощник»</b></link>','lead'))
qr=QrCodeWidget(URL);b=qr.getBounds();qr_d=Drawing(86,86,transform=[86/(b[2]-b[0]),0,0,86/(b[3]-b[1]),0,0]);qr_d.add(qr);story.append(qr_d)
note('Наведите камеру телефона на QR-код или нажмите ссылку. Версия для тестирования, без оплаты.')
note('Это описание функций, а не медицинская памятка. AI может ошибаться. При угрозе жизни звоните 112, не ждите ответа чата.')

page('01 / НАЧАЛО РАБОТЫ','Один профиль. Ваша история.','Сначала проверьте сведения, от которых зависит персональный ответ.')
card('Возраст обновляется сам','Укажите дату рождения ребёнка и его имя или домашнее имя. Для беременности - срок и дату, на которую он указан.','Помощник учитывает текущий возраст, а не число месяцев при регистрации.','Откройте «Профиль». После рождения смените этап и укажите дату рождения.')
card('Что помощник учитывает','Профиль, текущий разговор, подтверждённые вами заметки, последние записи дневника и результаты занятий.','Не нужно каждый раз рассказывать одно и то же.','Поправляйте неверные сведения. Предложение AI в карту попадёт только после вашего подтверждения.','#DDF6F3')
card('Новое: удобный вход в задачи','В «Моём дне» доступны план, дневник, развитие и безопасность дома, подготовка к врачу и тематические кнопки.','Можно начать с потребности, даже если трудно сформулировать вопрос.','Выберите раздел. В AI-сценариях запрос появится в чате: проверьте его и нажмите отправку.')
note('У мамы и папы отдельные аккаунты, данные не объединяются. В общих тестовых аккаунтах используйте только вымышленные сведения.')

page('02 / ЧТО НОВОГО','Совет превращается в действие','Небольшие шаги вместо длинного списка обязательств.')
card('План на пять дней','Подборка коротких занятий по возрасту или организационных шагов во время беременности.','Чтобы выбрать занятие без поиска и долгой подготовки.','«Мой день» → «Мой план» → «Подобрать пять дней». Задания можно выполнить, пропустить или удалить.')
card('Кнопка «В мой план»','Любой ответ можно превратить в редактируемую личную задачу.','Чтобы полезный совет не потерялся в переписке.','Под ответом нажмите «В мой план», оставьте одно действие, выберите дату и сохраните. Это не медицинское назначение.','#FFF0D8')
card('Результат и следующий шаг','Отметки «Помогло», «Пока непонятно», «Было трудно» и ваш комментарий доступны помощнику.','Следующий совет может учитывать ваш опыт.','Запишите результат в плане. Кнопка «Адаптировать с AI» подготовит вопрос. Трудные занятия не повторяются в автоматической подборке 14 дней.')
note('Можно выбрать дату возвращения к результату. Вопрос появится при открытии кабинета. Фоновые push пока не подключены. Кнопка «В календарь» выгружает нейтральное событие без имени ребёнка и сведений о здоровье.')

page('03 / ЧТО НОВОГО','Игры и перемены без спешки','Не нужно покупать специальные наборы или сравнивать ребёнка с другими.')
card('Игра из того, что дома','AI-сценарий с учётом возраста, свободного времени, интересов и доступных предметов.','Быстро придумать совместное занятие.','Выберите 2, 5, 10 или 20 минут и напишите, что есть дома. Уточните ограничения. Взрослый остаётся рядом.')
card('Понять поведение','Возможные объяснения ситуации и спокойные фразы для разговора с ребёнком.','Помочь родителю выбрать реакцию, а не навесить ярлык на ребёнка.','Опишите, что произошло до и после ситуации. AI не определяет диагноз и не знает мотивов ребёнка наверняка.','#EDE4FF')
card('Детский сад и подготовка к школе','Отдельные сценарии для адаптации, самостоятельности, общения и игр со словами.','Подготовиться к переменам в своём темпе.','Выберите нужную тему. Для маленького ребёнка помощник должен предлагать обычные возрастные игры, не школьные упражнения.')
note('Нет баллов, экзамена «готов ли к школе», обязательного чтения и обещаний ускорить развитие. Персональные задания AI нужно оценивать с учётом возможностей ребёнка.')

page('04 / ЧТО НОВОГО','Дневник, который помогает вспомнить','Записывайте только то, что полезно именно вам. Вести всё ежедневно не обязательно.')
card('Сон, кормление, настроение, заметки','Короткие записи с датой. Для сна можно указать длительность отдельного эпизода; для родителя - как прошёл день.','Сохранить наблюдения без сложных таблиц.','«Мой день» → «Дневник». Выберите тип, дату и при желании комментарий.')
card('Итоги недели','Показываются число записей, сумма введённых эпизодов сна, трудные дни и выполненные действия.','Заметить изменения в собственных записях, не сравнивая ребёнка с нормой из интернета.','Нажмите «Обсудить неделю с AI». Помощник получает последние записи и может предложить следующий небольшой шаг.','#DDF6F3')
card('Развитие и безопасный дом','Родитель отмечает события: переворачивается, ползает, встаёт, ходит или своё маленькое открытие. Список проверки дома дополняется.','Вовремя вспомнить о меняющемся окружении ребёнка.','Откройте «Развитие и дом», добавьте событие и пройдите появившиеся пункты.')
note('Сумма сна в дневнике - только то, что вы внесли, не полный сон за неделю. Повторение событий не доказывает причину или диагноз. Чек-лист дома не является полным аудитом безопасности.')

page('05 / ЧТО НОВОГО','До и после визита к врачу','Организация информации - да. Самостоятельная постановка диагноза - нет.')
card('Подготовка к приёму','Дата, повод, ваши вопросы и подтверждённые вами наблюдения в одном месте.','Чтобы не забыть важное на приёме.','Откройте «К врачу», добавьте запись. Кнопка «Подготовиться с AI» помогает сформулировать вопросы.')
card('Памятка для специалиста','Текстовый файл с вопросами, записями карты и последними заметками дневника.','Показать последовательность событий понятным списком.','Нажмите «Скачать памятку к приёму». Прочитайте файл перед передачей врачу: он содержит выбранные вами сведения.','#FFF0D8')
card('Указания после приёма','Дословная запись слов врача, которую можно перенести в личный план.','Не потерять указания и уточнения после визита.','Заполните поле после приёма; оно сохраняется при выходе из поля. «Дословно в мой план» копирует текст без изменения AI.')
note('Проверьте даты и формулировки. Непонятные названия, дозы и сроки уточняйте у врача, а не угадывайте с AI. Выгрузка является вашей памяткой, не медицинским документом.')

page('06 / ЧТО НОВОГО','Поддержка нужна и взрослым','Не нужно быть идеальным родителем, чтобы попросить о помощи.')
card('Ситуация сейчас','Быстрый выбор: ребёнок плачет, истерика, не хочет спать или нечем занять.','Сформулировать вопрос и получить короткий следующий шаг.','Выберите ситуацию и добавьте подробности. При угрозе жизни сразу 112. Чат не является службой экстренной помощи.')
card('Мне нужна поддержка','Бережный AI-разговор и небольшая пауза на выбранное время.','Разобраться, какая помощь нужна сейчас, и снизить нагрузку на ближайшие минуты.','Напишите о своём состоянии. Если есть риск навредить себе или ребёнку, не ждите чат: позовите взрослого рядом и обратитесь за срочной помощью.','#FBE7EC')
card('Папин режим','Отдельный сценарий с конкретной частью заботы и идеями времени с ребёнком.','Чтобы участие папы не сводилось к просьбе «помоги чем-нибудь».','Укажите свободное время и ситуацию. Помощник предложит посильное дело и занятие по возрасту.')
note('Эмоциональная поддержка AI не является психотерапией. Если состояние долго мешает жить, нужен живой специалист. Помощник не даёт психологических диагнозов.')

page('07 / ЧТО НОВОГО','Меньше печатать. Больше ясности.','Удобные инструменты с понятными ограничениями.')
card('Голосовой ввод и чтение ответа','«Сказать голосом» заполняет поле сообщения. «Прослушать» читает ответ, если установлен локальный русский голос.','Пользоваться помощником, когда неудобно печатать или читать.','Разрешите микрофон, проверьте распознанный текст и отправьте. Если функция недоступна, используйте диктовку клавиатуры телефона.')
card('Паспорт ответа','Под ответом можно посмотреть, на чём он основан, загружался ли официальный материал и когда.','Не путать уверенный тон AI с доказанной точностью.','Раскройте «На чём основан ответ». Для загрузки материала поставьте соответствующую отметку перед отправкой вопроса.','#DDF6F3')
card('Документы и выплаты','Подготовка вопросов для родителя в России и переход к официальному разделу СФР.','Понять, где уточнить условия для своей семьи.','Выберите «Документы и выплаты», укажите регион и вопрос. Не вводите номера паспортов, полисов и СНИЛС.')
note('Распознавание голоса может выполняться сервером провайдера браузера; сайт не сохраняет аудио. Каталог источников ограничен пятью страницами NHS, UNICEF и СФР. Это не поиск по всему интернету и не проверка каждого утверждения. Суммы и право на выплаты не рассчитываются.')

page('08 / ВАЖНО ЗНАТЬ','Вы управляете своими данными','Что стоит проверить перед первым разговором и как сообщить об ошибке.')
card('Отдельный аккаунт для личных вопросов','Профиль, история, дневник и план сохраняются на сервере проекта; контекст передаётся AI через CheapAI.','Чтобы понимать, где используется внесённая информация.','Во время теста используйте вымышленные сведения. Общие тестовые входы доступны всем, кто знает пароль.')
card('Оценка и жалоба под ответом','«Помогло», «Не помогло», «Неверный / опасный совет»; в настройках есть предложение улучшения.','Сообщить разработчику о проблеме с конкретным сценарием.','Опишите, что произошло. Передача профиля и последних сообщений в обращении требует отдельного согласия. Срочную помощь через форму не запрашивайте.','#EDE4FF')
card('Что пока не обещаем','Нет гарантии медицинской безошибочности, фоновых push, специалиста в чате, автоматического права на пособия или неограниченного интернет-поиска.','Чтобы возможности сервиса соответствовали ожиданиям.','Проверяйте важное с профильным специалистом. Результаты занятий и предпочтения можно менять, записи - удалять.')
story.append(p(f'<link href="{URL}" color="#6338C7"><b>Вернуться на сайт и открыть «Мой день» →</b></link>','lead'))
note('Описание обновления care-services-v3. Сентябрь 2026. Доступность голоса и официальных страниц зависит от браузера и сети. Никаких диагнозов, назначения лечения и оценки ребёнка по баллам.')

