 c.saveState();w,h=doc.pagesize;c.setFillColor(BG);c.rect(0,0,w,h,fill=1,stroke=0);c.setFillColor(PURPLE);c.roundRect(48,h-24,50,4,2,fill=1,stroke=0);c.setFont('DV',8);c.setFillColor(MUTED);c.drawString(48,25,'Мамин помощник · Что нового и как пользоваться');c.drawRightString(w-48,25,str(doc.page));c.restoreState()
